<?php
declare(strict_types=1);
date_default_timezone_set('America/New_York');

const REAL_FILE_NAME='install_weekly_standings_scrollbar_gutter_v001_20260921_115510pm.php';
const REAL_FILE_SHA256='dc51831a2444ac253f31e8cae0cb24b3b480e977ac1badd1d10de7eaab88e473';
const REAL_FILE_B64='';

function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function lint_php_file(string $p):array{
    if(!function_exists('shell_exec'))return ['ok'=>false,'output'=>'shell_exec unavailable'];
    $o=@shell_exec('php -l '.escapeshellarg($p).' 2>&1');
    if($o===null)return ['ok'=>false,'output'=>'[NULL returned by shell_exec()]'];
    $o=trim((string)$o);
    return ['ok'=>stripos($o,'No syntax errors detected')!==false,'output'=>$o];
}

$realPath=__DIR__.'/'.REAL_FILE_NAME;
$action=(string)($_POST['action']??'');$msg='';$lint=null;

if($action==='stage'){
    $p=base64_decode(REAL_FILE_B64,true);
    if($p===false||hash('sha256',$p)!==REAL_FILE_SHA256)$msg='FAIL — embedded installer verification failed.';
    else{
        if(is_file($realPath)){
            $existing=(string)@file_get_contents($realPath);
            if(hash('sha256',$existing)!==REAL_FILE_SHA256)$msg='FAIL — different file already exists with this filename.';
        }

        if($msg===''&&!is_file($realPath)){
            if(@file_put_contents($realPath,$p,LOCK_EX)===false)$msg='FAIL — could not stage the real installer.';
            else @chmod($realPath,0644);
        }

        if($msg===''){
            $lint=lint_php_file($realPath);
            $msg=!empty($lint['ok'])?'PASS — real installer staged, hash-matched, and PHP lint passed.':'FAIL — real installer lint failed.';
        }
    }
}

if($lint===null&&is_file($realPath)&&hash_file('sha256',$realPath)===REAL_FILE_SHA256)$lint=lint_php_file($realPath);
$ready=is_file($realPath)&&$lint!==null&&!empty($lint['ok'])&&hash_file('sha256',$realPath)===REAL_FILE_SHA256;
?>
<!doctype html>
<html>
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
