button,a{padding:10px 16px;border-radius:9px;border:0;color:#fff;background:#248c4b;text-decoration:none;font-weight:700}
a{background:#276fca}pre{white-space:pre-wrap;background:#111;padding:12px}
</style>
</head>
<body>
<h1>Weekly Standings Scrollbar Gutter Lint Gate</h1>
<div class="card">
<p><code><?php echo h(REAL_FILE_NAME);?></code></p>
<p><?php echo h($msg);?></p>
<?php if($lint!==null):?><pre><?php echo h($lint['output']);?></pre><?php endif;?>
<form method="post" style="display:inline"><input type="hidden" name="action" value="stage"><button>Stage + Lint Real Installer</button></form>
<?php if($ready):?><a href="<?php echo h(REAL_FILE_NAME);?>">Open Real Installer</a><?php endif;?>
</div>
</body></html>
